const items = $input.all();

const today = new Date();

// Today's month and date
const todayMonth = today.getMonth() + 1;
const todayDate = today.getDate();

return items
  .filter(item => {
    const birthday = String(item.json.Birthday || "").trim();

    if (!birthday) {
      return false;
    }

    // Birthday format: YYYY-MM-DD
    const parts = birthday.split("-");

    if (parts.length !== 3) {
      return false;
    }

    const birthMonth = Number(parts[1]);
    const birthDay = Number(parts[2]);

    // Check birthday month and date
    return birthMonth === todayMonth && birthDay === todayDate;
  })
  .map(item => ({
    json: {
      name: item.json.Name,
      birthday: item.json.Birthday,
      phone: item.json.Phone,
      wishSent: item.json["Wish Sent"],
      birthdayWish: item.json["Birthday Wish"]
    }
  }));
